package cryptosquare

import (
	"math"
	"strings"
	"unicode"
)

// Encode normalizes the plaintext (lower-casing it and removing
// punctuation and spaces), lays it out in a rectangle as square as
// possible, and reads it back down the columns, left to right.
func Encode(pt string) string {
	var plain strings.Builder
	for _, r := range pt {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			plain.WriteRune(unicode.ToLower(r))
		}
	}
	plain := plain.String()
	n := len(plain)
	if n == 0 {
		return ""
	}

	c := int(math.Ceil(math.Sqrt(float64(n))))
	r := (n + c - 1) / c

	var out strings.Builder
	for col := 0; col < c; col++ {
		if col > 0 {
			out.WriteByte(' ')
		}
		for row := 0; row < r; row++ {
			if idx := row*c + col; idx < n {
				out.WriteByte(plain[idx])
			} else {
				out.WriteByte(' ')
			}
		}
	}
	return out.String()
}

